import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        // 전체에 맞는지 검사하는 것과 일부를 찾는 것은 달라요.
        String text = "id=12";
        System.out.println(text.matches("[0-9]+"));
        System.out.println(Pattern.compile("[0-9]+").matcher(text).find());
    }
}

